parameters.jsCode:
const item = $('1. Receive Tech Intent Trigger').first().json;
const payload = item.body ? item.body : item;
const aiResp = $input.first().json;

let aiData = {};
if (aiResp && aiResp.candidates && aiResp.candidates[0]?.content?.parts?.[0]?.text) {
  try {
    aiData = JSON.parse(aiResp.candidates[0].content.parts[0].text);
  } catch(e) {}
}

const sender = payload.sender_email || payload.customer_email || payload.from || "guest@enterprise.com";
const senderName = payload.sender_name || payload.name || sender.split('@')[0];
const title = aiData.cleaned_title || payload.title || payload.subject || "Yêu cầu hỗ trợ sự cố kỹ thuật";
const description = payload.body || payload.text || payload.description || "Không có mô tả chi tiết";
const affectedModule = aiData.affected_module || "Hạ tầng Dịch vụ & API";
const reproduceSteps = aiData.reproduce_steps || [
  "1. Khách hàng gửi yêu cầu hỗ trợ qua email",
  "2. Hệ thống ghi nhận lỗi gián đoạn dịch vụ",
  "3. Kỹ thuật viên kiểm tra nhật ký log server"
];
const reproduceStepsText = Array.isArray(reproduceSteps) ? reproduceSteps.join('\n') : String(reproduceSteps);
const symptoms = aiData.error_symptoms || "Gián đoạn phản hồi dịch vụ";
const summary = aiData.technical_summary || description.substring(0, 200);

// Sinh mã vé chuẩn định dạng doanh nghiệp: TK-YYYYMMDD-XXXX
const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const randomNum = Math.floor(1000 + Math.random() * 9000);
const ticketCode = `TK-${dateStr}-${randomNum}`;

return [{
  json: {
    ticket_code: ticketCode,
    sender_email: sender,
    customer_email: sender,
    sender_name: senderName,
    title: title,
    description: description,
    summary: summary,
    category: payload.category || "Technical",
    priority: payload.priority || "P1 - Critical",
    affected_module: affectedModule,
    reproduce_steps: reproduceSteps,
    reproduce_steps_text: reproduceStepsText,
    error_symptoms: symptoms,
    technical_summary: summary,
    generated_at: now.toISOString()
  }
}];

const base = $('3. Generate Ticket Code ID Code').first().json;
const agentCandidates = $input.all().map(a => a.json);

let chosenAgent = null;
if (agentCandidates && agentCandidates.length > 0 && agentCandidates[0].email) {
  // Chọn KTV có active_tickets_count nhỏ nhất
  chosenAgent = agentCandidates[0];
}

const assignedTo = chosenAgent ? (chosenAgent.full_name || chosenAgent.name) : "Nguyễn Văn An";
const agentEmail = chosenAgent ? chosenAgent.email : "tranglee12306@gmail.com";
const agentId = chosenAgent ? chosenAgent.id : 1;

let slaHours = 8;
if (base.priority.includes('P1')) slaHours = 2;
else if (base.priority.includes('P2')) slaHours = 4;
else if (base.priority.includes('P3')) slaHours = 8;
else if (base.priority.includes('P4')) slaHours = 24;

const deadline = new Date(Date.now() + slaHours * 60 * 60 * 1000);
const formattedDeadline = deadline.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false });

const agentSubject = `📌 [GÁN VÉ ${base.ticket_code}] ${base.priority} - ${base.title}`;
const agentHtml = `<!DOCTYPE html>
<html lang="vi">
<head><meta charset="UTF-8"><title>Điều Phối Vé Hỗ Trợ</title></head>
<body style="margin:0;padding:0;background-color:#0f172a;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1e293b;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="padding:40px 15px;">
    <tr><td align="center">
      <table role="presentation" width="600" cellspacing="0" cellpadding="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 20px 40px rgba(0,0,0,0.3);max-width:600px;width:100%;">
        <tr>
          <td style="background:linear-gradient(135deg, #1e40af 0%, #3b82f6 100%);padding:25px 35px;color:#ffffff;">
            <div style="font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;">HELPDESK SLA DISPATCHER &bull; THUẬT TOÁN LEAST-BUSY</div>
            <h1 style="margin:8px 0 0 0;font-size:20px;font-weight:900;">ĐIỀU PHỐI VÉ SỰ CỐ MỚI</h1>
          </td>
        </tr>
        <tr>
          <td style="padding:30px 35px;">
            <p>Chào <strong>${assignedTo}</strong>,</p>
            <p>Hệ thống tự động đã gán vé sự cố kỹ thuật này cho bạn xử lý:</p>
            <table width="100%" cellspacing="0" cellpadding="10" style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;font-size:14px;margin:15px 0;">
              <tr><td width="35%" style="color:#64748b;font-weight:bold;">Mã vé:</td><td><strong style="color:#2563eb;">${base.ticket_code}</strong></td></tr>
              <tr><td style="color:#64748b;font-weight:bold;">Mức độ:</td><td><strong>${base.priority}</strong></td></tr>
              <tr><td style="color:#64748b;font-weight:bold;">Module ảnh hưởng:</td><td>${base.affected_module}</td></tr>
              <tr><td style="color:#64748b;font-weight:bold;">Hạn SLA phản hồi:</td><td><strong style="color:#dc2626;">${formattedDeadline} (${slaHours}h)</strong></td></tr>
              <tr><td style="color:#64748b;font-weight:bold;">Khách hàng:</td><td>${base.customer_email}</td></tr>
            </table>
            <div style="background:#eff6ff;padding:15px;border-radius:8px;border-left:4px solid #3b82f6;margin:15px 0;font-size:13px;">
              <strong>Bóc tách từ AI Ticket Extractor (Agent 3):</strong><br>
              ${base.technical_summary}
            </div>
            <div style="margin-top:24px;text-align:center;">
              <a href="http://localhost:3000/tickets" style="background:#2563eb;color:#ffffff;text-decoration:none;padding:12px 24px;border-radius:8px;font-weight:bold;display:inline-block;">Xử Lý Vé Trên Hệ Thống</a>
            </div>
          </td>
        </tr>
      </table>
    </td></tr>
  </table>
</body>
</html>`;

return [{
  json: {
    ...base,
    assigned_to: assignedTo,
    agent_email: agentEmail,
    assigned_agent_id: agentId,
    sla_hours: slaHours,
    sla_deadline: deadline.toISOString(),
    agent_email_subject: agentSubject,
    agent_email_html: agentHtml
  }
}];

