parameters.jsCode:
const finalData = $('5. Least-Busy Load Balancer Code').first().json;
return [{
  json: {
    status: 'SUCCESS',
    ticket_code: finalData.ticket_code,
    title: finalData.title,
    assigned_to: finalData.assigned_to,
    agent_email: finalData.agent_email,
    priority: finalData.priority,
    sla_deadline: finalData.sla_deadline,
    affected_module: finalData.affected_module,
    reproduce_steps: finalData.reproduce_steps,
    technical_summary: finalData.technical_summary,
    search_query: `${finalData.affected_module} ${finalData.title}`
  }
}];

const current = $input.first().json;

// Chuẩn bị Bridge Packet cho Luồng 4 (Thành viên 2 - RAG Knowledge Base & Thư nháp)
const bridgePayload = {
  ticket_code: current.ticket_code,
  search_query: current.search_query,
  technical_summary: current.technical_summary,
  customer_email: $('3. Generate Ticket Code ID Code').first().json.customer_email,
  ready_for_member2: true,
  status: "QUEUED_FOR_TV2_RAG"
};

return [{
  json: {
    status: "COMPLETED",
    message: "Quy trình tạo vé và điều phối SLA của Thành viên 1 hoàn tất thành công",
    ticket_code: current.ticket_code,
    assigned_agent: current.assigned_to,
    priority: current.priority,
    sla_deadline: current.sla_deadline,
    downstream_bridge: bridgePayload,
    dispatched_at: new Date().toISOString()
  }
}];
